// Nominatim → Overpass area id, then build the Overpass QL query.
// Overpass area ids are offset: relation + 3600000000, way + 2400000000.
const body   = $('Receive OSM Request').first().json.body || {};
const hit    = $input.first().json;

if (!hit || !hit.osm_id) {
  throw new Error(`Could not geocode area "${body.area}". Include the country, e.g. "Cairo, Egypt".`);
}

const offset  = hit.osm_type === 'relation' ? 3600000000 : 2400000000;
const areaId  = offset + Number(hit.osm_id);
const limit   = Math.min(Number(body.limit) || 100, 300);
const category = String(body.category || 'dentist').trim();

// Map a friendly category to the OSM tags that actually carry it. Many
// businesses are tagged under `shop`/`office`/`healthcare` rather than
// `amenity`, so we union several tag spellings or we miss most of them.
const TAGS = {
  dentist:           ['amenity=dentist', 'healthcare=dentist'],
  doctors:           ['amenity=doctors', 'healthcare=doctor'],
  clinic:            ['amenity=clinic', 'healthcare=clinic'],
  hospital:          ['amenity=hospital', 'healthcare=hospital'],
  pharmacy:          ['amenity=pharmacy', 'healthcare=pharmacy'],
  veterinary:        ['amenity=veterinary'],
  gym:               ['leisure=fitness_centre', 'amenity=gym'],
  restaurant:        ['amenity=restaurant'],
  cafe:              ['amenity=cafe'],
  hotel:             ['tourism=hotel'],
  hairdresser:       ['shop=hairdresser'],
  beauty:            ['shop=beauty'],
  car_repair:        ['shop=car_repair'],
  real_estate_agent: ['office=estate_agent'],
  lawyer:            ['office=lawyer'],
  school:            ['amenity=school'],
  travel_agency:     ['shop=travel_agency'],
};

const selectors = TAGS[category] || [`amenity=${category}`];
const union = selectors
  .map((sel) => {
    const [k, v] = sel.split('=');
    return `  nwr["${k}"="${v}"](area.a);`;
  })
  .join('\n');

const query = `[out:json][timeout:90];\narea(${areaId})->.a;\n(\n${union}\n);\nout center ${limit};`;

return [{ json: { query, areaId, category, limit, areaLabel: hit.display_name } }];

// OSM tags → the CRM lead schema.
// Keeps only rows we could actually contact; everything else is noise that
// would bloat the CRM and drag down list quality.
const meta = $('Build Overpass query').first().json;
const out  = [];

for (const item of $input.all()) {
  const el = item.json;
  const t  = el.tags || {};

  const company = (t.name || t['name:en'] || '').trim();
  const phone   = (t.phone || t['contact:phone'] || t['contact:mobile'] || '').trim();
  const email   = (t.email || t['contact:email'] || '').trim();
  const website = (t.website || t['contact:website'] || '').trim();

  // Must be identifiable AND reachable somehow.
  if (!company) continue;
  if (!phone && !email && !website) continue;

  const address = [t['addr:street'], t['addr:housenumber'], t['addr:city'], t['addr:country']]
    .filter(Boolean).join(', ');

  const osmUrl = `https://www.openstreetmap.org/${el.type}/${el.id}`;

  const notes = [
    `Source: OpenStreetMap (${meta.areaLabel || 'unknown area'})`,
    address        ? `Address: ${address}`            : null,
    website        ? `Website: ${website}`            : null,
    t.opening_hours? `Hours: ${t.opening_hours}`      : null,
    t['addr:city'] ? `City: ${t['addr:city']}`        : null,
    `OSM: ${osmUrl}`,
    '',
    `Channels — phone: ${phone ? 'YES' : 'no'} | email: ${email ? 'YES' : 'no'} | website: ${website ? 'YES' : 'no'}`,
  ].filter((l) => l !== null).join('\n');

  out.push({
    json: {
      // The ingest API accepts company-only leads and falls back name<->company.
      name:     company,
      company,
      email,               // '' is normalised to null server-side
      phone,
      category: String(meta.category || '').slice(0, 100),
      source:   'openstreetmap',
      notes,
    },
  });
}

return out;
